window.FZ = window.FZ || {};

/* 科目档案：每门课自己的学习动作、随身材料、卡点，以及真正属于这门课的考题。
   通用事件里的 {速记}{核心}{必背}{作业}{难点}{刷题App}{背} 全部由这里取值，
   所以数学分析不会再出现"背单词卡"，法学也不会盯着一黑板公式。 */

function Q(title, text, a, b, c) {
  return {
    title: title, text: text,
    choices: [a, b, c].map(function (x) {
      return { label: x[0], fx: { mod: x[1], s: x[2], m: x[3] }, result: x[4] };
    })
  };
}

