FZ.profile = function (subject, major) {
  const hit = FZ.SUBJECTS[subject];
  if (hit) return hit;
  const fb = FZ.MAJOR_FALLBACK[major];
  if (fb) return fb;
  return {
    major: major, kind: 'general', credit: 3,
    drill: FZ.DEFAULT_LEX.drill, core: FZ.DEFAULT_LEX.core, memo: FZ.DEFAULT_LEX.memo,
    work: FZ.DEFAULT_LEX.work, hard: FZ.DEFAULT_LEX.hard, app: FZ.DEFAULT_LEX.app, verb: FZ.DEFAULT_LEX.verb,
    exam: FZ.GENERIC_EXAM
  };
};

